export function lookupLocalPincode(pin) {
  const record = PINCODE_DATABASE[pin];
  if (!record) return null;
  return {
    pincode: pin,
    found: true,
    serviceable: record[0] === 1,
    area: record[1] || 'Local Area',
    branch: record[2] || '',
    district: record[2] || '',
    state: record[3] || 'India',
    fastTrack: record[4] === 1,
    cod: true,
    prepaid: true,
    tat: record[4] === 1 ? '1-2 Business Days' : '2-4 Business Days',
    remarks: record[0] === 1 ? 'Standard door-to-door delivery available' : 'Special pickup required'
  };
}
